SELECT c.claim_id,c.fraud_flag,c.severity,c.claim_amount,COALESCE(SUM(p.payment_amount),0) total_paid,COUNT(DISTINCT e.claim_event_id) event_count FROM claims c LEFT JOIN payments p ON c.claim_id=p.claim_id LEFT JOIN claim_events e ON c.claim_id=e.claim_id GROUP BY c.claim_id,c.fraud_flag,c.severity,c.claim_amount ORDER BY fraud_flag DESC,total_paid DESC;
SELECT c.claim_id,c.claim_amount,c.sum_insured,c.fraud_flag,COUNT(e.claim_event_id) investigation_events FROM claims c LEFT JOIN claim_events e ON c.claim_id=e.claim_id GROUP BY c.claim_id,c.claim_amount,c.sum_insured,c.fraud_flag HAVING c.fraud_flag=1 OR c.claim_amount>c.sum_insured;
